/**
 * Moves a milestone's live, still-open issues to `toMilestoneId` (or out of
 * any milestone when `null`). Closed and archived issues stay where they are.
 * Returns the ids of the issues that moved.
 */
export async function moveOpenIssuesOfMilestone(
  orgId: OrgId,
  fromMilestoneId: MilestoneId,
  toMilestoneId: MilestoneId | null,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .update(issues)
    .set({ milestoneId: toMilestoneId, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.milestoneId, fromMilestoneId),
          livePredicate(issues.archivedAt, {}),
          notInArray(issues.status, [...TERMINAL_STATUSES]),
        ),
      ),
    )
    .returning({ id: issues.id })
    .all();

  return rows.map((row) => row.id as IssueId);
}

/** Live-issue counts per milestone: total and the open (non-terminal) part. */
export async function countIssuesByMilestone(
  orgId: OrgId,
  milestoneIds: readonly MilestoneId[],
): Promise<ReadonlyMap<MilestoneId, { total: number; open: number }>> {
  if (milestoneIds.length === 0) return new Map();

  const rows = getDb()
    .select({
      milestoneId: issues.milestoneId,
      total: count(),
      open: sql<number>`sum(case when ${notInArray(issues.status, [...TERMINAL_STATUSES])} then 1 else 0 end)`,
    })
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          inArray(issues.milestoneId, [...milestoneIds]),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .groupBy(issues.milestoneId)
    .all();

  return new Map(
    rows.map((row) => [
      row.milestoneId as MilestoneId,
      { total: row.total, open: Number(row.open ?? 0) },
    ]),
  );
}

