  const row = getDb()
    .insert(milestones)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      name: input.name,
      targetDate: input.targetDate,
      closedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
  return toMilestone(row);
}

export async function updateMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
  patch: {
    name?: string;
    targetDate?: IsoTimestamp | null;
    closedAt?: IsoTimestamp | null;
  },
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({
