/**
 * Milestone lifecycle: create, rename/re-date, close (moving the open issues
 * on) and reopen, plus the progress read model.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, assertNotArchived
 */
import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { emit } from "@/lib/event-bus";
import {
  isMilestoneOpen,
  isMilestoneOverdue,
  MilestoneStateError,
  milestoneNameKey,
} from "@/lib/milestones";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as milestoneRepo from "@/server/repositories/milestone-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { toIsoTimestamp } from "@/types/common";
import {
  actorEnvelope,
  NotFoundError,
  projectResource,
  requireFound,
} from "./_support";
import type {
  CloseMilestoneInput,
  CreateMilestoneInput,
  UpdateMilestoneInput,
} from "@/schemas/milestone";
import type {
  IsoTimestamp,
  IssueId,
  MilestoneId,
  OrgId,
  ProjectId,
} from "@/types/common";
import type { Actor } from "@/types/member";
import type { Milestone, MilestoneWithProgress } from "@/types/milestone";
import type { Project } from "@/types/project";

export async function createMilestone(
  actor: Actor,
  input: CreateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  const name = input.name.trim();
  await assertNameFree(input.orgId, project.id, name, null);
  await assertRoomForOpen(input.orgId, project.id, name);

  const milestone = await milestoneRepo.insertMilestone({
    orgId: input.orgId,
    projectId: project.id,
    name,
    targetDate: normaliseDate(input.targetDate ?? null),
  });

  await emit("milestone.created", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
  });

  return milestone;
}

export async function updateMilestone(
  actor: Actor,
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const { milestone } = await loadForWrite(
    actor,
    input.orgId,
    input.milestoneId,
  );

  const name = input.name === undefined ? undefined : input.name.trim();
  if (name !== undefined) {
    await assertNameFree(input.orgId, milestone.projectId, name, milestone.id);
  }

  return milestoneRepo.updateMilestone(input.orgId, milestone.id, {
    name,
    targetDate:
      input.targetDate === undefined
        ? undefined
        : normaliseDate(input.targetDate),
  });
}

/**
 * Closes a milestone. Its live open issues move to `moveOpenIssuesTo` — which
 * must be another open milestone of the same project — or out of any
 * milestone when that is `null`. Every check runs before the first write, so
 * a refused close changes nothing and announces nothing.
 */
export async function closeMilestone(
  actor: Actor,
  input: CloseMilestoneInput,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);

  const { milestone } = await loadForWrite(
    actor,
    input.orgId,
    input.milestoneId,
  );
  if (!isMilestoneOpen(milestone)) {
    throw new MilestoneStateError("closed", milestone.id);
  }

  const targetId = input.moveOpenIssuesTo ?? null;
  if (targetId !== null) {
    if (targetId === milestone.id) {
      throw new NotFoundError("Milestone", targetId);
    }
    await requireOpenMilestoneInProject(
      input.orgId,
      milestone.projectId,
      targetId,
    );
  }

  const movedIssueIds = await issueRepo.moveOpenIssuesOfMilestone(
    input.orgId,
    milestone.id,
    targetId,
  );
  const closed = await milestoneRepo.updateMilestone(input.orgId, milestone.id, {
    closedAt: toIsoTimestamp(new Date()),
  });

  await emit("milestone.closed", {
    ...actorEnvelope(actor),
    milestoneId: closed.id,
    projectId: closed.projectId,
    movedToMilestoneId: targetId,
    movedIssueIds,
  });

  return { milestone: closed, movedIssueIds };
}

export async function reopenMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  assertOrgScope(actor, orgId);

  const { milestone } = await loadForWrite(actor, orgId, milestoneId);
  if (isMilestoneOpen(milestone)) {
    throw new MilestoneStateError("already_open", milestone.id);
  }
  await assertRoomForOpen(orgId, milestone.projectId, milestone.id);

  const reopened = await milestoneRepo.updateMilestone(orgId, milestone.id, {
    closedAt: null,
  });

  await emit("milestone.reopened", {
    ...actorEnvelope(actor),
    milestoneId: reopened.id,
    projectId: reopened.projectId,
  });

  return reopened;
}

/** Listing works on archived projects too: it is a read. */
export async function listMilestones(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly MilestoneWithProgress[]> {
  assertOrgScope(actor, orgId);

  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:read", projectResource(project));

  const milestones = await milestoneRepo.listMilestonesForProject(
    orgId,
    project.id,
  );
  return withProgress(orgId, milestones);
}

export async function getMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneWithProgress> {
  assertOrgScope(actor, orgId);

  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  const project = await requireProject(orgId, milestone.projectId);
  assertCan(actor, "project:read", projectResource(project));

  const [result] = await withProgress(orgId, [milestone]);
  return result as MilestoneWithProgress;
}

/**
 * The milestone an issue may be put into: one of the issue's own project
 * (anything else is `NotFoundError`, as if it did not exist) that is open.
 */
export async function requireOpenMilestoneInProject(
  orgId: OrgId,
  projectId: ProjectId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  const milestone = await milestoneRepo.findMilestoneById(orgId, milestoneId);
  if (milestone === null || milestone.projectId !== projectId) {
    throw new NotFoundError("Milestone", milestoneId);
  }
  if (!isMilestoneOpen(milestone)) {
    throw new MilestoneStateError("closed", milestone.id);
  }
  return milestone;
}

/** The shared gate of every milestone write: found, permitted, project live. */
async function loadForWrite(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<{ milestone: Milestone; project: Project }> {
  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  const project = await requireProject(orgId, milestone.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);
  return { milestone, project };
}

async function requireProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  return requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
}

/** Names are unique per project across open and closed milestones alike. */
async function assertNameFree(
  orgId: OrgId,
  projectId: ProjectId,
  name: string,
  exceptId: MilestoneId | null,
): Promise<void> {
  const key = milestoneNameKey(name);
  const existing = await milestoneRepo.listMilestonesForProject(
    orgId,
    projectId,
  );
  if (
    existing.some(
      (other) => other.id !== exceptId && milestoneNameKey(other.name) === key,
    )
  ) {
    throw new MilestoneStateError("name_taken", name);
  }
}

async function assertRoomForOpen(
  orgId: OrgId,
  projectId: ProjectId,
  subject: string,
): Promise<void> {
  const open = await milestoneRepo.countOpenMilestones(orgId, projectId);
  if (open >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError("too_many_open", subject);
  }
}

/** Stored in one canonical form so target dates compare as strings. */
function normaliseDate(value: IsoTimestamp | null): IsoTimestamp | null {
  return value === null ? null : toIsoTimestamp(value);
}

async function withProgress(
  orgId: OrgId,
  milestones: readonly Milestone[],
): Promise<readonly MilestoneWithProgress[]> {
  const counts = await issueRepo.countIssuesByMilestone(
    orgId,
    milestones.map((milestone) => milestone.id),
  );
  const now = new Date();

  return milestones.map((milestone) => {
    const tally = counts.get(milestone.id) ?? { total: 0, open: 0 };
    const progress = {
      total: tally.total,
      open: tally.open,
      closed: tally.total - tally.open,
    };
    return {
      milestone,
      progress,
      overdue: isMilestoneOverdue(milestone, progress, now),
    };
  });
}
EOF

