    await expect(ms.updateMilestone(o, { orgId: org, milestoneId: a.id, name: " beta" })).rejects.toBeInstanceOf(MilestoneStateError);
    await expect(ms.createMilestone(t.actors.viewer, { orgId: org, projectId: t.project.id, name: "X", targetDate: null })).rejects.toThrow();
    const acts = await activityRepo.listActivity({ orgId: org, limit: 100, cursor: null } as never);
    expect(acts.items.filter((x) => x.action.startsWith("milestone.")).map((x) => x.action).sort()).toEqual(["milestone.closed", "milestone.created", "milestone.created", "milestone.created", "milestone.reopened"]);
