    for (let k = 0; k < 7; k++) await ms.createMilestone(o, { orgId: org, projectId: t.project.id, name: `m${k}`, targetDate: null });
    await expect(ms.createMilestone(o, { orgId: org, projectId: t.project.id, name: "over", targetDate: null })).rejects.toMatchObject({ reason: "too_many_open" });
